#!/usr/bin/env python3"""OmniVoice demo with FlashInfer acceleration (WSL2 / Linux).Reuses the official build_demo (Voice Clone + Voice Design tabs) andapplies flashinfer packed-attention acceleration on top.Usage:    .venv/bin/python demo_flashinfer.py \        --model /mnt/e/llama-models/models/OmniVoice-bf16 \        --port 9877 --no-asr --ip 0.0.0.0"""import argparseimport loggingimport torchfrom omnivoice import OmniVoicefrom omnivoice.cli.demo import build_demofrom omnivoice.models.omnivoice_flashinfer import apply_flashinferdef main() -> int:    logging.basicConfig(        level=logging.INFO,        format="%(asctime)s %(name)s %(levelname)s: %(message)s",    )    parser = argparse.ArgumentParser(prog="omnivoice-demo-flashinfer")    parser.add_argument("--model", default="k2-fsa/OmniVoice",                        help="Model checkpoint path or HF repo id.")    parser.add_argument("--device", default="cuda")    parser.add_argument("--ip", default="0.0.0.0")    parser.add_argument("--port", type=int, default=9877)    parser.add_argument("--share", action="store_true", default=False)    parser.add_argument("--no-asr", action="store_true", default=False)    parser.add_argument("--no-cuda-graph", action="store_true", default=False,                        help="Disable CUDA graph capture (flashinfer still on).")    parser.add_argument("--graph-buckets", default="5,10,15,20,30",                        help="Duration buckets (sec) for CUDA graph capture; "                        "each bucket owns one graph so VRAM stays bounded. "                        "Empty string = tight packing per length (unbounded).")    args = parser.parse_args()    logging.info("Loading model from %s, device=%s ...", args.model, args.device)    model = OmniVoice.from_pretrained(        args.model,        device_map=args.device,        dtype=torch.float16,        load_asr=not args.no_asr,    )    print("Model loaded.")    buckets = [int(b) for b in args.graph_buckets.split(",") if b.strip()] \        if args.graph_buckets.strip() else None    apply_flashinfer(        model,        enable_cuda_graph=not args.no_cuda_graph,        cuda_graph_buckets=buckets,    )    print("FlashInfer applied. cuda_graph =", not args.no_cuda_graph,          "| buckets =", buckets)    demo = build_demo(model, args.model)    # ── 合成产物自动清理(2026-10-13, 天工开帧/Vidu 组件版) ──────────────────────    # gradio 自带的 delete_cache 只删 blocks.temp_file_sets 里**已登记**的临时文件; 本服务    # 把 wav 直接落盘返回 → 不在登记集里 → 那个机制对本站无效(实测 11.5 分钟的文件仍在)。    # 所以在服务进程内起一个守护线程按 mtime 清理: 零额外进程、开销只有每    # OMNIVOICE_GC_EVERY 秒一次小目录遍历; 解码进 PCM 后这些 wav 已无用(客户端早已取走)。    def _start_cache_gc() -> None:        import os        import pathlib as _p        import threading        import time        every = int(os.environ.get("OMNIVOICE_GC_EVERY", "600"))   # 扫描间隔(秒)        age = int(os.environ.get("OMNIVOICE_GC_AGE", "900"))       # 超过这个年龄就删(秒)        root = _p.Path(os.environ.get("GRADIO_TEMP_DIR") or "/tmp/gradio")        print(f"[gc] 合成产物自动清理: 每 {every}s 扫一次 {root}, 删超过 {age}s 的", flush=True)        def loop() -> None:            while True:                time.sleep(every)                try:                    now = time.time()                    for f in root.rglob("*"):                        try:                            if f.is_file() and now - f.stat().st_mtime > age:                                f.unlink()                        except OSError:                            pass                except Exception:          # noqa: BLE001  清理失败绝不影响服务                    pass        threading.Thread(target=loop, name="omnivoice-cache-gc", daemon=True).start()    _start_cache_gc()    demo.queue().launch(        server_name=args.ip,        server_port=args.port,        share=args.share,    )    return 0if __name__ == "__main__":    raise SystemExit(main())